const tick=()=>new Promise(r=>setTimeout(r,15));async function until(fn,label){for(let i=0;i<200;i++){if(fn())return;await tick();}try{opened.at(-1).window.eval('render()')}catch(e){console.error(e.stack)}console.error(opened.at(-1).auditErrors);console.error(opened.at(-1).window.document.querySelector('#main').innerHTML.slice(0,2500));throw Error('Timeout: '+label);}
function fixture(){const d=SM.fresh();Object.assign(d,{title:'UI Audit League',venue:'Sofia',phase:'live',athletes:['Иван Иванов','Петър Петров','Георги Георгиев'].map((name,i)=>({id:'a'+i,bib:i+1,name})),events:[{id:'e',names:{bg:'Камион',en:'Truck'},mode:'race',target:20,cap:60,secondary:'none',reviewed:true}],results:{e:{a1:{status:'ok',time:11,penalty:0,deduction:0,note:''}}},audience:{enabled:true}});return d;}
function saved(doc,opts={}){return {doc,queue:[],drafts:{},sync:null,view:'overview',eventIndex:0,athleteId:'a0',...opts};}
function make(role,{record,db=new IDBFactory(),remote={doc:SM.document(fixture()),offline:false},url,quota=false}={}){const errors=[],console=new VirtualConsole();console.on('jsdomError',e=>{if(!e.message.includes('navigation'))errors.push(e);});const dom=new JSDOM(pages[role],{url:url||(role==='judge'?'https://audit.test/strongman/strongman-arena':'https://audit.test/strongman/visitors'),runScripts:'dangerously',pretendToBeVisual:true,virtualConsole:console,beforeParse(w){Object.assign(w,{TextEncoder,TextDecoder,Blob,AbortSignal,structuredClone,indexedDB:db});w.matchMedia=()=>({matches:false,addEventListener(){}});w.scrollTo=()=>{};w.confirm=()=>true;w.prompt=()=>null;w.HTMLDialogElement.prototype.showModal=function(){this.open=true;};w.HTMLDialogElement.prototype.close=function(){this.open=false;this.dispatchEvent(new w.Event('close'));};w.URL.createObjectURL=()=> 'blob:audit';w.URL.revokeObjectURL=()=>{};Object.defineProperty(w.navigator,'clipboard',{value:{writeText:async()=>{}}});if(record)w.localStorage.setItem('strongman-arena-v1',typeof record==='string'?record:JSON.stringify(record));if(quota){const original=w.Storage.prototype.setItem;w.Storage.prototype.setItem=function(key,value){if(key==='strongman-arena-v1'&&String(value).length>200)throw new w.DOMException('Quota exceeded','QuotaExceededError');return original.call(this,key,value);};}w.fetch=async(input,opts={})=>{if(remote.offline)throw TypeError('Offline');const p=new URL(input,w.location.href).pathname;const reply=(status,body,headers={})=>new Response(status===304?null:JSON.stringify(body),{status,headers:{'Content-Type':'application/json',...headers}});if(p.endsWith('/viewer')){if(!remote.doc.data.audience?.enabled)return reply(404,{error:'VIEWER_DISABLED'});const tag='"viewer-'+remote.doc.revision+'"';if(opts.headers?.['If-None-Match']===tag)return reply(304,null,{ETag:tag});return reply(200,{...SM.publicState(remote.doc.data),revision:remote.doc.revision},{ETag:tag});}if(p.endsWith('/state'))return reply(200,{doc:remote.doc});if(p.endsWith('/op')){try{remote.doc=SM.apply(remote.doc,JSON.parse(opts.body));return reply(200,{doc:remote.doc});}catch(e){return reply(409,{error:e.message});}}return reply(404,{error:'UNKNOWN'});};}});dom.auditErrors=errors;opened.push(dom);return {dom,w:dom.window,remote,db,errors};}
const find=(x,selector)=>{const el=x.w.document.querySelector(selector);assert.ok(el,'Missing '+selector);return el;};
async function click(x,selector){find(x,selector).click();await tick();}
async function input(x,selector,value){const el=find(x,selector);el.value=value;el.dispatchEvent(new x.w.Event('input',{bubbles:true}));await tick();}
async function change(x,selector,value){const el=find(x,selector);el.value=value;el.dispatchEvent(new x.w.Event('change',{bubbles:true}));await tick();}
async function submit(x,selector){find(x,selector).dispatchEvent(new x.w.Event('submit',{bubbles:true,cancelable:true}));await tick();}
