 await test('Confirmed new competition downloads original, retains season/archive/publication and supports undo',async()=>{const data=fixture(),round=fixture();round.id='previous-round';round.phase='finished';round.results.e.a0={status:'ok',time:10,penalty:0,deduction:0,note:''};round.results.e.a2={status:'ok',time:12,penalty:0,deduction:0,note:''};const season=SM.seasonFresh();season.title='Test season';season.athletes=round.athletes.map(a=>({id:'profile-'+a.id,name:a.name}));season.competitions=[{id:round.id,data:SM.competitionSnapshot(round),entries:round.athletes.map(a=>({athleteId:a.id,seasonId:'profile-'+a.id,status:'ranked'}))}];data.season=season;const x=make('judge',{record:saved(SM.document(data))});await until(()=>x.w.eval('storageReady'),'boot');const downloads=[];x.w.download=(name,blob)=>downloads.push({name,blob});await click(x,'.overview-heading-actions [data-act="new"]');assert.equal(downloads.length,0);await click(x,'[data-season-choice="yes"]');assert.equal(downloads.length,1);const backup=JSON.parse(await downloads[0].blob.text());assert.deepEqual(backup.doc.data,data);assert.equal(x.w.eval('doc.data.phase'),'setup');assert.notEqual(x.w.eval('doc.data.id'),data.id);assert.equal(x.w.eval('doc.data.athletes.length'),0);assert.equal(x.w.eval('doc.data.events.length'),0);assert.deepEqual(JSON.parse(x.w.eval('JSON.stringify(doc.data.season)')),season);assert.equal(x.w.eval('doc.data.audience.enabled'),true);assert.equal(x.w.document.activeElement.id,'title');await until(()=>x.w.eval('storagePending===0'),'new saved');const y=make('judge',{record:x.w.localStorage.getItem('strongman-arena-v1'),db:x.db});await until(()=>y.w.document.querySelector('#setupForm'),'new reload');assert.equal(y.w.eval('doc.data.season.competitions.length'),1);await click(y,'#nav [data-act="more"]');await click(y,'[data-view="history"]');await click(y,'[data-act="undo"]');assert.deepEqual(JSON.parse(y.w.eval('JSON.stringify(doc.data)')),data);assert.equal(y.errors.length,0);});
