 await test('Demo step changes ignore forged or stale messages; exit and restart preserve a typed score',async()=>{const x=make('judge',{record:saved(SM.document(fixture()),{view:'scoring'})});await until(()=>x.w.document.querySelector('#time'),'scoring');await input(x,'#time','12,75');await until(()=>x.w.eval('storagePending===0'),'draft durable');const raw=x.w.localStorage.getItem('strongman-arena-v1');await click(x,'#nav [data-act="demoLaunch"]');const frame=find(x,'#demoFrame'),oldToken=frame.getAttribute('srcdoc').match(/"token":"([^"]+)"/)[1];await click(x,'#demoNext');assert.equal(find(x,'#demoCount').textContent,'2 / 28');x.w.dispatchEvent(new x.w.MessageEvent('message',{source:frame.contentWindow,data:{smDemo:true,token:oldToken,kind:'close'}}));assert.ok(find(x,'#smDemo').open);x.w.dispatchEvent(new x.w.MessageEvent('message',{source:x.w,data:{smDemo:true,token:oldToken,kind:'viewer'}}));assert.equal(find(x,'#demoCount').textContent,'2 / 28');await click(x,'#demoClose');assert.equal(find(x,'#time').value,'12,75');assert.equal(x.w.localStorage.getItem('strongman-arena-v1'),raw);await click(x,'#nav [data-act="demoLaunch"]');assert.equal(find(x,'#demoCount').textContent,'1 / 28');await click(x,'#demoClose');assert.equal(x.errors.length,0);});
 await test('Event configuration drafts restore mode-dependent controls and unchecked review after reload and reopening',async()=>{const data=fixture();data.phase='setup';data.results={};const x=make('judge',{record:saved(SM.document(data),{view:'setup'})});await until(()=>x.w.document.querySelector('#setupForm'),'setup');await click(x,'[data-act="editEvent"]');await change(x,'#mode','distance');await change(x,'#unit','deg');const check=find(x,'#eventForm [name="reviewed"]');check.checked=false;check.dispatchEvent(new x.w.Event('change',{bubbles:true}));await until(()=>x.w.eval('storagePending===0'),'event draft persisted');const y=make('judge',{record:x.w.localStorage.getItem('strongman-arena-v1'),db:x.db});await until(()=>y.w.document.querySelector('#eventForm'),'restored dialog');assert.equal(find(y,'#mode').value,'distance');assert.equal(find(y,'#distanceUnitField').hidden,false);assert.equal(find(y,'#unit').value,'deg');assert.equal(find(y,'#secondary').value,'none');assert.equal(find(y,'#eventForm [name="reviewed"]').checked,false);find(y,'#dialog').close();await click(y,'[data-act="editEvent"]');assert.equal(find(y,'#mode').value,'distance');assert.equal(find(y,'#unit').value,'deg');assert.equal(find(y,'#eventForm [name="reviewed"]').checked,false);await submit(y,'#eventForm');assert.equal(y.w.eval('doc.data.events[0].unit'),'deg');assert.equal(y.w.eval('doc.data.events[0].reviewed'),false);assert.equal(y.w.eval('drafts.event||null'),null);});
 await test('Legacy event drafts normalize a stale tiebreak without changing the confirmed event',async()=>{const data=fixture();data.phase='setup';data.results={};const doc=SM.document(data),drafts={event:{id:'e',base:SM.clone(data.events),values:{bg:'Градуси',en:'Degrees',mode:'distance',unit:'deg',target:'0',cap:'60',secondary:'all',weights:'',notes:''}}};const x=make('judge',{record:saved(doc,{view:'setup',drafts})});await until(()=>x.w.document.querySelector('#eventForm'),'legacy event draft');assert.equal(find(x,'#mode').value,'distance');assert.equal(find(x,'#unit').value,'deg');assert.equal(find(x,'#secondary').value,'none');assert.equal(find(x,'#eventForm [name="reviewed"]').checked,false);assert.equal(x.w.eval('doc.data.events[0].mode'),'race');await submit(x,'#eventForm');assert.equal(x.w.eval('doc.data.events[0].mode'),'distance');assert.equal(x.w.eval('doc.data.events[0].secondary'),'none');});
 await test('Spectator background choices preserve result context, persist locally and never duplicate controls',async()=>{const x=make('visitor');await until(()=>x.w.document.querySelector('.leaderboard-person'),'viewer');assert.equal(x.w.document.documentElement.dataset.audienceBackground,'standard');await input(x,'#search','Петър');const before=x.w.eval('JSON.stringify(state)');await click(x,'[data-audience-open]');await click(x,'[data-audience-choice="poster"]');assert.equal(x.w.document.documentElement.dataset.audienceBackground,'poster');assert.equal(x.w.localStorage.getItem('sm-visitor-background-v1'),'poster');assert.equal(find(x,'#search').value,'Петър');assert.equal(x.w.document.querySelectorAll('.leaderboard-person').length,1);assert.equal(x.w.eval('JSON.stringify(state)'),before);assert.equal(x.w.document.querySelector('#audienceBackgroundDialog'),null);assert.equal(new URL(x.w.eval('publicURL()')).searchParams.get('background'),'poster');x.w.eval('render();render()');assert.equal(x.w.document.querySelectorAll('.topactions [data-audience-open]').length,1);await click(x,'.topactions [data-audience-open]');await click(x,'[data-audience-choice="standard"]');assert.equal(x.w.document.documentElement.dataset.audienceBackground,'standard');assert.equal(new URL(x.w.location.href).searchParams.has('background'),false);assert.equal(find(x,'#search').value,'Петър');assert.equal(x.errors.length,0);});
 await test('Shared background links accept only known choices and remain available in TV and disabled publication',async()=>{const remote={doc:SM.document(fixture()),offline:false},x=make('visitor',{remote,url:'https://audit.test/strongman/visitors?background=logo'});await until(()=>x.w.document.querySelector('#tvMode'),'viewer');assert.equal(x.w.document.documentElement.dataset.audienceBackground,'logo');await click(x,'#tvMode');assert.equal(x.w.document.querySelectorAll('.tv-controls [data-audience-open]').length,1);await click(x,'.tv-controls [data-audience-open]');await click(x,'[data-audience-choice="poster"]');assert.ok(x.w.document.body.classList.contains('tv-page'));assert.equal(x.w.document.querySelectorAll('.leaderboard-person').length,3);remote.doc.data.audience.enabled=false;await x.w.eval('poll()');assert.equal(x.w.document.querySelector('.leaderboard-person'),null);assert.equal(x.w.document.querySelectorAll('.topactions [data-audience-open]').length,1);const y=make('visitor',{url:'https://audit.test/strongman/visitors?background=invalid'});await until(()=>y.w.document.querySelector('#tvMode'),'safe viewer');assert.equal(y.w.document.documentElement.dataset.audienceBackground,'standard');assert.equal(y.errors.length,0);});
 await test('Live spectator updates retain keyboard focus; opening an athlete focuses the profile heading',async()=>{const remote={doc:SM.document(fixture()),offline:false},x=make('visitor',{remote});await until(()=>x.w.document.querySelector('[data-athlete="a1"]'),'viewer');find(x,'[data-athlete="a1"]').focus();remote.doc=SM.apply(remote.doc,SM.operation(remote.doc,[{path:['data','results','e','a0'],next:{status:'ok',time:9,penalty:0,deduction:0,note:''}}],'Other judge'));await x.w.eval('poll()');assert.equal(x.w.document.activeElement.dataset.athlete,'a1');await click(x,'[data-athlete="a1"]');assert.ok(x.w.document.activeElement.matches('.athlete-profile-section h2'));find(x,'#allAthletes').focus();await click(x,'#allAthletes');assert.equal(x.w.document.activeElement.getAttribute('data-overall'),'');assert.equal(x.errors.length,0);});
 await test('Spectator focus survives overall, filters and TV transitions in English',async()=>{const x=make('visitor');await until(()=>x.w.document.querySelector('[data-result-mode="event"]'),'viewer');await click(x,'#language');await click(x,'[data-result-mode="event"]');find(x,'[data-overall]').focus();await x.w.eval('poll()');assert.ok(x.w.document.activeElement.hasAttribute('data-overall'));find(x,'#visitorFilters summary').focus();await x.w.eval('poll()');assert.equal(x.w.document.activeElement,find(x,'#visitorFilters summary'));find(x,'#tvMode').focus();await click(x,'#tvMode');assert.equal(x.w.document.activeElement.id,'exitTv');assert.equal(find(x,'#tvStatus').getAttribute('role'),null);await click(x,'#exitTv');assert.equal(x.w.document.activeElement.id,'tvMode');assert.equal(x.errors.length,0);});
 await test('Escape from paged TV returns keyboard focus to its launcher',async()=>{const data=fixture();for(let i=3;i<8;i++)data.athletes.push({id:'a'+i,bib:i+1,name:'Athlete '+i});const x=make('visitor',{remote:{doc:SM.document(data),offline:false}});await until(()=>x.w.document.querySelector('#tvMode'),'viewer');await click(x,'#tvMode');find(x,'#tvNext').focus();x.w.document.dispatchEvent(new x.w.KeyboardEvent('keydown',{key:'Escape',bubbles:true}));assert.equal(x.w.document.activeElement.id,'tvMode');assert.equal(x.w.document.body.classList.contains('tv-page'),false);assert.equal(x.errors.length,0);});
 await test('Season round links keep focus on updates and focus the opened athlete profile',async()=>{const data=fixture();data.id='r1';data.phase='finished';data.results.e={};for(let i=0;i<3;i++)data.results.e['a'+i]={status:'ok',time:10+i,penalty:0,deduction:0,note:''};const season=SM.seasonFresh();season.title='Fictional season';season.athletes=data.athletes.map((a,i)=>({id:'s'+i,name:a.name}));season.competitions=[{id:'r1',data:SM.competitionSnapshot(data),entries:data.athletes.map((a,i)=>({athleteId:a.id,seasonId:'s'+i,status:'ranked'}))}];data.season=season;const remote={doc:SM.document(data),offline:false},x=make('visitor',{remote,url:'https://audit.test/strongman/visitors?tab=season'});await until(()=>x.w.document.querySelector('[data-round][data-profile="a1"]'),'season viewer');find(x,'[data-round][data-profile="a1"]').focus();remote.doc=SM.apply(remote.doc,SM.operation(remote.doc,[{path:['data','season','title'],next:'Fictional season update'}],'Other judge'));await x.w.eval('poll()');assert.equal(x.w.document.activeElement.dataset.profile,'a1');await click(x,'[data-round][data-profile="a1"]');assert.ok(x.w.document.activeElement.matches('.athlete-profile-section h2'));assert.equal(x.errors.length,0);});
 await test('Hidden spectator tabs skip polling and refresh on return without repeating the clock as a live announcement',async()=>{const x=make('visitor');await until(()=>x.w.document.querySelector('.leaderboard-person'),'viewer');let hidden=true,calls=0;Object.defineProperty(x.w.document,'hidden',{configurable:true,get:()=>hidden});const fetch=x.w.fetch;x.w.fetch=(...args)=>{calls++;return fetch(...args);};x.w.eval('pollWhenVisible()');await tick();assert.equal(calls,0);hidden=false;x.w.document.dispatchEvent(new x.w.Event('visibilitychange'));await until(()=>calls===1,'visible refresh');assert.equal(find(x,'#liveState').getAttribute('role'),'status');assert.equal(find(x,'#updated').getAttribute('role'),null);let announcements=0;const observer=new x.w.MutationObserver(records=>{announcements+=records.length;});observer.observe(find(x,'#liveState'),{childList:true,characterData:true,subtree:true});await x.w.eval('poll()');await x.w.eval('poll()');await tick();observer.disconnect();assert.equal(announcements,0,'unchanged 304 polls do not rewrite live status');assert.equal(x.errors.length,0);});
